const { body, headers } = $input.first().json;
const trace_id = String($execution.id);
const isObject = body !== null && typeof body === 'object' && !Array.isArray(body);
const supplied = isObject ? body : {};
const action = Object.hasOwn(supplied, 'action') ? supplied.action : 'status';
const dataset = Object.hasOwn(supplied, 'dataset') ? supplied.dataset : 'live';
const hasMonth = Object.hasOwn(supplied, 'month');
const mediaType = String(headers?.['content-type'] ?? '').split(';', 1)[0].trim().toLowerCase();

function invalid(validationError) {
  return [{ json: {
    action: isObject && typeof action === 'string' ? action : null,
    trace_id,
    route: 3,
    validationError,
    childInput: {},
  } }];
}

if (mediaType !== 'application/json' || !isObject) {
  return invalid('Send a JSON object with Content-Type: application/json.');
}
if (Object.keys(body).some((key) => !['action', 'dataset', 'month'].includes(key))) {
  return invalid('Only action, dataset and month are allowed.');
}
if (!['check', 'status', 'report', 'get_report'].includes(action)) {
  return invalid('action must be check, status, report or get_report.');
}
if (!['live', 'demo'].includes(dataset)) {
  return invalid('dataset must be live or demo.');
}
if (action === 'check' && dataset !== 'live') {
  return invalid('check requires the live dataset.');
}
if ((action === 'check' || action === 'status') && hasMonth) {
  return invalid('month is only allowed for report and get_report.');
}
if (action === 'get_report' && !hasMonth) {
  return invalid('month is required for get_report.');
}

let month = '';
if (action === 'report' || action === 'get_report') {
  const now = new Date();
  const currentMonth = now.toISOString().slice(0, 7);
  if (hasMonth) {
    month = body.month;
  } else {
    now.setUTCDate(1);
    now.setUTCMonth(now.getUTCMonth() - 1);
    month = now.toISOString().slice(0, 7);
  }
  if (typeof month !== 'string' || month.length !== 7 ||
      !/^\d{4}-(0[1-9]|1[0-2])$/.test(month) || month.startsWith('0000') ||
      month > currentMonth) {
    return invalid('month must be a valid YYYY-MM through the current UTC month.');
  }
}

const routes = { check: 0, status: 1, get_report: 1, report: 2 };
const route = routes[action];
const childInput = { dataset, trace_id };
if (route !== 0) childInput.month = month;
if (route === 1) childInput.action = action;

return [{ json: { action, trace_id, route, childInput } }];

const request = $('Validate Gateway Request').first().json;
const statusByCode = {
  INVALID_REQUEST: 400,
  REPORT_NOT_FOUND: 404,
  STALE_REPORT: 409,
  NOT_ELIGIBLE: 409,
  DEPENDENCY_ERROR: 502,
};

function respond(status, fields) {
  return [{ json: {
    status,
    body: { ...fields, action: request.action, execution_id: request.trace_id },
  } }];
}

function failure(code, error) {
  return respond(statusByCode[code], { ok: false, code, error });
}

if (request.validationError) {
  return failure('INVALID_REQUEST', request.validationError);
}

const items = $input.all();
const reply = items.length === 1 ? items[0].json : null;
if (reply?.ok === true && reply.result !== null && typeof reply.result === 'object' && !Array.isArray(reply.result)) {
  return respond(200, { ok: true, result: reply.result });
}
if (reply?.ok === false && typeof reply.code === 'string' &&
    Object.hasOwn(statusByCode, reply.code) &&
    typeof reply.error === 'string' && reply.error.trim() !== '') {
  return failure(reply.code, reply.error);
}
return failure('DEPENDENCY_ERROR', 'The sub-workflow failed or returned an invalid response.');
